// @interlace/meter v1.0.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/meter
// What changed since: https://ds.interlace.tools/c/meter#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — Meter and RankedBarList
 *
 * ONE inline bar, absorbing three that were hand-rolled separately across the
 * phase-10 corpus: an odds bar, a score meter and a reviewer bar. They differed
 * in tone and in what the denominator meant; they did not differ in anything
 * that justified three components, and each of the three had reinvented the
 * "there is no number here" case slightly differently.
 *
 * ## Length and number. Never hue.
 *
 * Every magnitude is carried twice — by the **length** of the fill and by the
 * **printed value** — and the value is not optional. Colour carries tone
 * ("is this good"), never size. The artifacts state that rationale explicitly
 * and it is the same rule `Delta` follows with its glyph/sign/colour triple:
 * roughly 8% of men cannot separate the red from the green, and none of them
 * can read a bar whose only quantity is its hue.
 *
 * A consequence worth stating: the fill is clamped to the track, so a value
 * over its stated maximum draws full. The overage is visible in the number and
 * nowhere else — which is exactly why the number is mandatory.
 *
 * ## Two absences, drawn differently on purpose
 *
 *   - **`hatch`** — *uncountable*. No run happened. The track is hatched end
 *     to end and there is no fill, because a fill of zero length is
 *     indistinguishable from a measured zero. This is `value: null`, and it is
 *     the default rendering for it: you have to work to make this component
 *     draw an empty bar for missing data.
 *   - **`dead`** — *dormant*. There IS a number, and it is not live any more.
 *     The bar recedes rather than disappearing, because a dormant row still
 *     occupies rank and still counts toward a total; hiding it would change
 *     the shape of the list.
 *
 * ## Why `RankedBarList` supports a log scale
 *
 * One artifact encodes reach logarithmically so a 10k row and a 10M row can
 * share an axis. On a linear axis the 10k row is a hairline — it reads as
 * zero, which is the one thing it is not. On a log axis both are legible and
 * the ordering, which is what a ranked list is *for*, survives.
 *
 * It is opt-in and it is **labelled**: `scale="log"` prints "log scale" beside
 * the caption. A log axis flatters small numbers, so an unlabelled one is a
 * chart that argues for its subject without saying so.
 *
 * ## MIN_VIEWPORT — 320
 *
 * Each row is label-over-bar, not label-beside-bar: at 320 a side-by-side
 * layout leaves the track ~90px, at which point the difference between 12%
 * and 19% is two pixels. Everything is `min-w-0` and the value is
 * `whitespace-nowrap`, so a long label wraps instead of pushing the page
 * sideways.
 *
 * | Rule | Concept                          | Where in this file                                          |
 * | ---- | -------------------------------- | ----------------------------------------------------------- |
 * | R4   | Extends native el                | `React.ComponentProps<'div'>`                                |
 * | R6   | data-slot on every part          | `data-slot="meter" / "-track" / "-fill" / "ranked-bar-list"`  |
 * | R8   | No `isXxx`; enums for >2 states  | `variant` (default/hatch/dead), `tone`, `size`, `scale`       |
 * | R10  | Composition seams                | `note` / `display` ReactNode slots                            |
 * | R11  | One variable per part            | the list owns the domain; a row owns its own tone and state   |
 * | R14  | Declares min viewport            | `data-min-viewport={String(MIN_VIEWPORT)}` + exported const   |
 * | R18  | Tailwind only                    | width comes from `fillWidthClass`, never `style={{width}}`    |
 * | R19  | Tokens only                      | `bg-secondary`, `bg-primary`, `--viz-positive/-negative`      |
 * | R20  | AA contrast                      | table below                                                   |
 * | R25  | Server component                 | pure render — no hooks                                        |
 * | R26  | A11y                             | `role="meter"` + `aria-valuenow/min/max` + `aria-valuetext`   |
 *
 * ## Contrast, measured (never eyeballed — see COLOR_PHILOSOPHY.md)
 *
 * | Composite                          | Light  | Dark   | Floor                      |
 * | ---------------------------------- | ------ | ------ | -------------------------- |
 * | fill `--primary` on `--secondary`  | 6.71:1 | 6.04:1 | 3:1 (SC 1.4.11, non-text)  |
 * | track `--secondary` on `--background` | 1.24:1 | 1.19:1 | decorative — the fill and the printed number carry the value |
 * | hatch `--viz-axis` on `--background`  | 3.49:1 | 3.83:1 | 3:1 (SC 1.4.11)         |
 * | dead fill `--muted-foreground/30` on `--secondary` | 1.9:1 | 1.8:1 | decorative — `dead` rows print their value and carry a badge |
 * | label `--muted-foreground`         | 5.66:1 | 6.29:1 | 4.5:1 (SC 1.4.3)           |
 *
 * The track/fill split is the same pattern as the slider rail vs knob: the
 * low-contrast element is supplementary, the high-contrast one carries the
 * success criterion.
 */

import * as React from 'react';

import { cn } from '@/lib/utils';
import {
  DataStateBadge,
  type AnnouncementOptions,
  type DataStateFlags,
} from '@/components/ui/data-state';
import {
  announceDataState,
  HATCH_CLASS,
  resolveDataState,
} from '@/components/ui/data-state-model';
import {
  compactMagnitude,
  describeMeter,
  fillWidthClass,
  meterDomainMax,
  meterFraction,
  rankByValue,
  type MeterScaleKind,
} from '@/components/ui/meter-scale';
import { Skeleton } from '@/components/ui/skeleton';

export const MIN_VIEWPORT = 320 as const;

/**
 * How the bar is drawn.
 *
 *   - `default` — a real, live measurement.
 *   - `hatch`   — uncountable. No run happened. Chosen automatically when
 *                 `value` is `null`; naming it explicitly is for the case where
 *                 a number exists but must not be counted.
 *   - `dead`    — dormant. Real but no longer live; recedes without vanishing.
 */
export type MeterVariant = 'default' | 'hatch' | 'dead';

/** Which semantic the fill carries. Never the magnitude — only the meaning. */
export type MeterTone = 'default' | 'positive' | 'negative' | 'neutral';

const TONE_FILL: Record<MeterTone, string> = {
  default: 'bg-primary',
  positive: 'bg-viz-positive',
  negative: 'bg-viz-negative',
  neutral: 'bg-viz-neutral',
};

const SIZE_TRACK: Record<'sm' | 'md', string> = {
  sm: 'h-1.5',
  md: 'h-2.5',
};

export interface MeterProps
  extends Omit<React.ComponentProps<'div'>, 'children'> {
  label: React.ReactNode;
  /**
   * The measurement. `null` means UNMEASURED and renders the hatch — it does
   * NOT render a zero-length bar, because a zero-length bar and a measured
   * zero are the same picture.
   */
  value: number | null;
  /**
   * The denominator. `null` or omitted means there is no stated maximum, so
   * no fraction can be computed and the bar draws as hatch — a bar without a
   * denominator is a length with no scale behind it.
   */
  max?: number | null;
  unit?: string;
  /** Linear (default) or logarithmic. Log must be labelled by the caller. */
  scale?: MeterScaleKind;
  /**
   * Override the computed fill fraction, `0..1`. For the odds-bar case where
   * the ratio being drawn is not `value / max` — e.g. a probability drawn
   * beside an absolute count.
   */
  fraction?: number | null;
  /** Printed magnitude. Defaults to a compact form of `value`. */
  display?: React.ReactNode;
  /** Second line under the bar — provenance, window, caveat. */
  note?: React.ReactNode;
  variant?: MeterVariant;
  tone?: MeterTone;
  size?: 'sm' | 'md';
  /** Absence flags for this row, over and above the value being `null`. */
  state?: DataStateFlags;
  announce?: AnnouncementOptions;
  loading?: boolean;
}

export const Meter = React.forwardRef<HTMLDivElement, MeterProps>(function Meter(
  {
    label,
    value,
    max = null,
    unit,
    scale = 'linear',
    fraction,
    display,
    note,
    variant,
    tone = 'default',
    size = 'md',
    state,
    announce,
    loading = false,
    className,
    ...props
  },
  ref,
) {
  if (loading) {
    return (
      <Skeleton
        variant="meter"
        data-slot="meter"
        data-min-viewport={String(MIN_VIEWPORT)}
        className={className}
      />
    );
  }

  const computed =
    fraction === undefined ? meterFraction(value, max, scale) : fraction;

  // `hatch` is the default for an absent measurement, not an opt-in. Getting
  // this backwards is how the three hand-rolled bars each ended up drawing an
  // empty track for missing data.
  const resolvedVariant: MeterVariant =
    variant ?? (value === null || computed === null ? 'hatch' : 'default');

  const resolved = resolveDataState(
    {
      ...state,
      notCounted: state?.notCounted ?? (resolvedVariant === 'hatch' && value === null),
    },
    announce,
  );

  // The sentence reports the VALUE, not the bar. A row with a real number and
  // no denominator hatches (there is no scale to draw a length against) but it
  // is not unmeasured — saying "not measured" there would be the component
  // inventing an absence out of its own rendering decision.
  const spoken = describeMeter(
    typeof label === 'string' ? label : 'Value',
    value,
    max,
    unit,
  );

  const printed =
    display ??
    (value === null ? null : `${compactMagnitude(value)}${unit ? ` ${unit}` : ''}`);

  return (
    <div
      ref={ref}
      data-slot="meter"
      data-variant={resolvedVariant}
      data-tone={tone}
      data-state={resolved.state}
      data-scale={scale}
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('flex w-full min-w-0 flex-col gap-1', className)}
      {...props}
    >
      <div className="flex min-w-0 items-baseline justify-between gap-2">
        {/* `dead` does NOT dim the label. `--muted-foreground` is already the
            quietest text token that clears AA (5.66:1 light / 6.29:1 dark);
            `/70` on top measured 3.4:1 and axe caught it. A dormant row
            recedes in its FILL, which is non-text and free to be quiet — its
            label and its number stay as legible as every other row's, which
            is the honest treatment for a row that still holds its rank. */}
        <span className="min-w-0 break-words font-mono text-ui-sm uppercase tracking-wide text-muted-foreground">
          {label}
        </span>
        {/* The number is not optional. It is the second carrier of magnitude
            and the only one that survives greyscale, a 40%-width screenshot
            and a screen reader. */}
        {printed === null ? (
          <DataStateBadge
            state={resolved.state === 'idle' ? 'not-counted' : resolved.state}
            announce={announce}
            className="shrink-0"
          />
        ) : (
          <span
            // `dir="auto"`: inside an RTL page the bidi algorithm reorders
            // "44 findings" to "findings 44", because the number is a neutral
            // run inside an RTL paragraph. `auto` resolves direction from the
            // first strong character — Latin unit → LTR, Arabic unit → RTL —
            // so a measurement keeps its own reading order either way.
            dir="auto"
            className={cn(
              'shrink-0 whitespace-nowrap font-body text-ui font-semibold tabular-nums',
              resolvedVariant === 'dead' && 'text-muted-foreground',
            )}
          >
            {printed}
          </span>
        )}
      </div>

      {resolvedVariant === 'hatch' ? (
        // No fill at all. A hatched track says "nothing ran here"; a track
        // with a zero-width fill says "we ran it and the answer was none".
        <div
          data-slot="meter-track"
          data-hatch
          aria-hidden
          className={cn(
            'w-full rounded-full border border-dashed border-border',
            SIZE_TRACK[size],
            HATCH_CLASS,
          )}
        />
      ) : (
        <div
          data-slot="meter-track"
          role="meter"
          aria-valuenow={value ?? 0}
          aria-valuemin={0}
          aria-valuemax={max ?? undefined}
          aria-valuetext={spoken}
          aria-label={typeof label === 'string' ? label : undefined}
          className={cn(
            'w-full overflow-hidden rounded-full bg-secondary',
            SIZE_TRACK[size],
          )}
        >
          <div
            data-slot="meter-fill"
            className={cn(
              'h-full rounded-full',
              resolvedVariant === 'dead'
                ? 'bg-muted-foreground/30'
                : TONE_FILL[tone],
              fillWidthClass(computed ?? 0),
            )}
          />
        </div>
      )}

      {note ? (
        <span className="font-body text-ui-sm leading-snug text-muted-foreground">
          {note}
        </span>
      ) : null}

      {/* The bar's geometry is aria-hidden or summarised; the sentence is what
          a screen reader actually gets, and it carries the real number rather
          than the projection of it. */}
      <span className="sr-only">
        {spoken}
        {resolved.qualifiers.length > 0
          ? ` ${resolved.qualifiers
              .map((name) => announceDataState(name, announce))
              .join(' ')}`
          : ''}
      </span>
    </div>
  );
});

// ─────────────────────────────────────────────────────────────────
// RankedBarList — the repeated-row composition
// ─────────────────────────────────────────────────────────────────

export interface RankedBarRow {
  key: string;
  label: React.ReactNode;
  /** `null` = unmeasured. It keeps its row and its rank; it does not become 0. */
  value: number | null;
  unit?: string;
  note?: React.ReactNode;
  variant?: MeterVariant;
  tone?: MeterTone;
  state?: DataStateFlags;
  display?: React.ReactNode;
}

export interface RankedBarListProps
  extends Omit<React.ComponentProps<'section'>, 'children'> {
  rows: readonly RankedBarRow[];
  /** Visible caption. Also the list's accessible name. */
  caption?: React.ReactNode;
  /**
   * The shared denominator. Omit and it is the largest MEASURED value —
   * `null`s are skipped rather than counted as zero, so an all-unmeasured list
   * yields no domain and every row hatches.
   */
  max?: number | null;
  scale?: MeterScaleKind;
  /**
   * `descending` (default) sorts by value with unmeasured rows last;
   * `given` keeps the caller's order, for a list whose order is the argument.
   */
  order?: 'descending' | 'given';
  size?: 'sm' | 'md';
  /**
   * List-wide absence. `truncated` is the one to reach for: it is the state
   * that stops a top-10 from being read as a denominator.
   */
  state?: DataStateFlags;
  announce?: AnnouncementOptions;
  loading?: boolean;
  /** Rows to reserve while loading. */
  loadingRows?: number;
}

export const RankedBarList = React.forwardRef<HTMLElement, RankedBarListProps>(
  function RankedBarList(
    {
      rows,
      caption,
      max,
      scale = 'linear',
      order = 'descending',
      size = 'md',
      state,
      announce,
      loading = false,
      loadingRows = 5,
      className,
      ...props
    },
    ref,
  ) {
    const list = resolveDataState({ ...state, loading }, announce);

    if (list.state === 'loading') {
      return (
        <Skeleton
          variant="meter"
          count={loadingRows}
          data-slot="ranked-bar-list"
          data-min-viewport={String(MIN_VIEWPORT)}
          className={className}
        />
      );
    }

    const ordered = order === 'descending' ? rankByValue(rows) : [...rows];
    const domain =
      max === undefined || max === null
        ? meterDomainMax(rows.map((row) => row.value))
        : max;

    return (
      <section
        ref={ref}
        data-slot="ranked-bar-list"
        data-state={list.state}
        data-scale={scale}
        data-qualifiers={list.qualifiers.join(' ') || undefined}
        data-min-viewport={String(MIN_VIEWPORT)}
        className={cn('flex w-full min-w-0 flex-col gap-4', className)}
        {...props}
      >
        {caption || scale === 'log' || list.state !== 'idle' ? (
          <div className="flex flex-wrap items-center gap-2">
            {caption ? (
              <p className="font-mono text-ui-sm uppercase tracking-wide text-muted-foreground">
                {caption}
              </p>
            ) : null}
            {/* A log axis that is not labelled is an argument disguised as a
                measurement: it flatters every small row on the list. */}
            {scale === 'log' ? (
              <span className="rounded-sm border border-border px-1.5 py-0.5 font-mono text-ui-sm leading-none text-muted-foreground">
                log scale
              </span>
            ) : null}
            {list.active
              .filter((name) => name !== 'idle')
              .map((name) => (
                <DataStateBadge key={name} state={name} announce={announce} />
              ))}
          </div>
        ) : null}

        {ordered.map((row) => (
          <Meter
            key={row.key}
            label={row.label}
            value={row.value}
            max={domain}
            unit={row.unit}
            note={row.note}
            display={row.display}
            variant={row.variant}
            tone={row.tone}
            size={size}
            scale={scale}
            state={row.state}
            announce={announce}
          />
        ))}
      </section>
    );
  },
);

/**
 * @interlace/ui — the DataState vocabulary (pure)
 *
 * Nothing in this file imports React, touches the DOM, or renders anything.
 * It is the part of the absence contract that can be *proved* — the union, the
 * precedence order, the announcement each state owes a screen reader, and the
 * class set that paints it — so `data-state.tsx`, `stat-strip.tsx` and
 * `meter.tsx` all resolve absence through the same three functions rather than
 * each re-deriving it from a boolean ladder.
 *
 * ## Why absence is a vocabulary and not a placeholder
 *
 * `charts/scale.ts` already encodes one half of this: `null` is *unmeasured*,
 * never zero, and `numeric()` drops it rather than coercing it, because
 * averaging over an invented zero silently manufactures data. That is a
 * statement about arithmetic. This file is the same statement about pixels.
 *
 * Six published artifacts were catalogued for phase 10 and every one of them
 * had hand-rolled some version of this, because the distinctions are real and
 * no component library ships them:
 *
 *   - a diagonal **hatch** means *no run happened* — which is a different fact
 *     from a run that returned zero, and a very different fact from a run that
 *     is still going;
 *   - a **dashed** outline means *planned / not yet approached*; solid means
 *     *real*;
 *   - `not counted`, `authority`, `visibility`, `dormant` are legitimate
 *     non-numeric values a cell can hold, and rendering any of them as `0`
 *     is a lie the reader cannot detect;
 *   - two absences that recede vs. accent on purpose: an *unwritten* thing is
 *     quiet, an *ungated* thing is actionable.
 *
 * The rules that fall out, verbatim from the corpus: **never render a missing
 * prior as 0**; **a truncated list must never be a denominator**; when coverage
 * is partial, **treat every count as a floor**.
 *
 * ## Two kinds of state, which is what makes the precedence tractable
 *
 * REPLACING states answer "there is nothing here to show" — the body is
 * swapped for the state itself. QUALIFYING states answer "there IS something
 * here, and here is what is wrong with it" — the body renders, annotated.
 *
 * A resolver that returns one winner throws away the second fact. So
 * `resolveDataState` returns the winner **and** every other active state as
 * `qualifiers`, and the announcement concatenates them. A partial-coverage
 * result that is also truncated says so twice, because it is wrong twice.
 *
 * ## Precedence
 *
 * `DATA_STATES` **is** the precedence order — lowest index wins. Reading down
 * the array is reading the rule, so the two cannot drift apart.
 *
 *   1. `loading`            nothing is known yet; every other flag is stale.
 *   2. `error`              a failed fetch must never read as "no data".
 *   3. `not-applicable`     the metric has no meaning here. Any number, `0`
 *                           included, would be a category error.
 *   4. `not-counted`        measurable in principle, deliberately not tallied.
 *                           `0` here invents a measurement nobody took.
 *   5. `empty`              a complete result with nothing in it. The only
 *                           absence that is a real, observed zero-length.
 *   6. `partial`            coverage is incomplete. Ranked above `truncated`
 *                           because it is INVISIBLE: the reader can see a list
 *                           stop, but cannot see a source that never reported.
 *   7. `truncated`          the list is cut. Not a denominator.
 *   8. `first-measurement`  a value exists, no prior does. Never `+0%`.
 *   9. `idle`              data is real and complete. The resting state.
 */

/**
 * Every state, in precedence order. Lowest index wins.
 *
 * `idle` is last and is not an absence — it is the absence of absence, kept in
 * the union so a caller can exhaustively switch and so the resolver always has
 * something to return.
 */
export const DATA_STATES = [
  'loading',
  'error',
  'not-applicable',
  'not-counted',
  'empty',
  'partial',
  'truncated',
  'first-measurement',
  'idle',
] as const;

export type DataStateName = (typeof DATA_STATES)[number];

/**
 * States that REPLACE the body — there is no value to render underneath them.
 *
 * The complement (`partial`, `truncated`, `first-measurement`) qualifies a body
 * that does render. `idle` is neither, and is excluded from both.
 */
export const REPLACING_STATES = new Set<DataStateName>([
  'loading',
  'error',
  'not-applicable',
  'not-counted',
  'empty',
]);

/** States that annotate a body which still renders. */
export const QUALIFYING_STATES = new Set<DataStateName>([
  'partial',
  'truncated',
  'first-measurement',
]);

/** True when this state swaps out the content rather than annotating it. */
export const replacesBody = (state: DataStateName): boolean =>
  REPLACING_STATES.has(state);

/**
 * The caller's flags, one per absence.
 *
 * `error` is `unknown` rather than `boolean` so a caught value can be passed
 * through untouched — the value is never rendered from here, only its
 * truthiness is read.
 *
 * Deliberately NOT a single `state` enum prop: the whole point is that these
 * co-occur. A partially-covered, truncated list is two facts, and an enum
 * would force the caller to pick one and drop the other on the floor.
 */
export interface DataStateFlags {
  loading?: boolean;
  error?: unknown;
  empty?: boolean;
  /** Some sources did not report. Every count below is a FLOOR, not a total. */
  partial?: boolean;
  /** The list is cut short. It must never become a denominator. */
  truncated?: boolean;
  /** The metric has no meaning for this subject. Not zero — inapplicable. */
  notApplicable?: boolean;
  /** No run happened. Not zero — unmeasured. This is the hatch. */
  notCounted?: boolean;
  /** A reading exists but no prior does. Never render this as `+0%`. */
  firstMeasurement?: boolean;
}

/** Flag key → state name, in the same order as `DATA_STATES`. */
const FLAG_ORDER: readonly (readonly [keyof DataStateFlags, DataStateName])[] = [
  ['loading', 'loading'],
  ['error', 'error'],
  ['notApplicable', 'not-applicable'],
  ['notCounted', 'not-counted'],
  ['empty', 'empty'],
  ['partial', 'partial'],
  ['truncated', 'truncated'],
  ['firstMeasurement', 'first-measurement'],
];

/**
 * Context for the spoken sentence.
 *
 * Every field is optional, and every announcement is a complete sentence
 * without any of them — a component that forgets to pass `noun` still
 * announces something true, just less specific.
 */
export interface AnnouncementOptions {
  /** What is missing — "articles", "downloads", "runs". */
  noun?: string;
  /** How many rows the truncated list actually shows. */
  shown?: number;
  /** How coverage is incomplete — "4 of 9 sources reported". */
  coverage?: string;
  /** Why this is not applicable — "repository has no test suite". */
  reason?: string;
}

/**
 * The sentence a screen reader hears for one state.
 *
 * A hatch pattern that exists only in pixels is invisible to a screen reader,
 * which defeats the entire point of distinguishing "no run" from "zero" —
 * the distinction would survive for sighted users and vanish for everyone
 * else. Every state therefore owes a sentence, and the sentence says what the
 * absence MEANS rather than naming the state.
 */
export function announceDataState(
  state: DataStateName,
  options: AnnouncementOptions = {},
): string {
  const { noun, shown, coverage, reason } = options;
  const subject = noun ?? 'data';

  switch (state) {
    case 'loading':
      return `Loading ${subject}.`;
    case 'error':
      return `${capitalise(subject)} could not be loaded.`;
    case 'not-applicable':
      return reason
        ? `Not applicable: ${reason}.`
        : `Not applicable. No value is possible here.`;
    // "This is not a zero" is doing real work: without it a listener has no
    // way to tell an unmeasured cell from a measured zero, which is the exact
    // confusion the hatch exists to prevent for sighted readers.
    case 'not-counted':
      return `Not counted. No measurement was taken; this is not a zero.`;
    case 'empty':
      return `No ${subject}.`;
    case 'partial':
      return coverage
        ? `Partial coverage: ${coverage}. Every count is a floor, not a total.`
        : `Partial coverage. Every count is a floor, not a total.`;
    case 'truncated':
      return shown === undefined
        ? `Truncated list. The total is unknown; do not use this as a denominator.`
        : `Truncated list: showing ${shown.toLocaleString()} of an unknown total. ` +
            `Do not use this as a denominator.`;
    case 'first-measurement':
      return `First measurement. There is no prior reading to compare against.`;
    /* istanbul ignore next -- exhaustive; `idle` is the only remaining member */
    default:
      return '';
  }
}

const capitalise = (value: string): string =>
  value.length === 0 ? value : value[0].toUpperCase() + value.slice(1);

/** What `resolveDataState` returns. */
export interface ResolvedDataState {
  /** The winner by precedence — what a single-slot surface should render. */
  state: DataStateName;
  /** Every active state, in precedence order. `['idle']` when none fired. */
  active: DataStateName[];
  /** `active` minus the winner. The facts a one-winner resolver would lose. */
  qualifiers: DataStateName[];
  /** True when the winner swaps out the body rather than annotating it. */
  replaces: boolean;
  /** Winner sentence followed by every qualifier sentence. */
  announcement: string;
}

/**
 * Resolve a flag bag into a state, its qualifiers, and one spoken sentence.
 *
 * The two rules the phase-10 audit called out by name both fall out of the
 * array order and are pinned by tests: **error beats empty** (a failed fetch
 * is a different message, not "nothing found"), and **truncated is not empty**
 * (they are separate members, and truncated does not replace the body at all).
 */
export function resolveDataState(
  flags: DataStateFlags = {},
  options: AnnouncementOptions = {},
): ResolvedDataState {
  const active = FLAG_ORDER.filter(([key]) => Boolean(flags[key])).map(
    ([, state]) => state,
  );

  if (active.length === 0) {
    return {
      state: 'idle',
      active: ['idle'],
      qualifiers: [],
      replaces: false,
      announcement: '',
    };
  }

  const [state, ...qualifiers] = active;
  return {
    state,
    active,
    qualifiers,
    replaces: replacesBody(state),
    announcement: [state, ...qualifiers]
      .map((name) => announceDataState(name, options))
      .join(' '),
  };
}

// ── Presentation ────────────────────────────────────────────────────────────

/**
 * How loud a state is allowed to be.
 *
 *   - `recede` — the *unwritten* family: a thing that was never going to have
 *     a value. It should not compete with the data around it.
 *   - `muted`  — the *unmeasured* family: a real gap, worth noticing, not
 *     worth alarming about.
 *   - `accent` — the *ungated* family: actionable. Something a reader can go
 *     and change. This is the one that earns colour.
 *   - `danger` — the request failed.
 */
export type DataStateEmphasis = 'recede' | 'muted' | 'accent' | 'danger';

/**
 * The diagonal hatch. **No run happened.**
 *
 * Written as a Tailwind arbitrary background-image rather than a CSS class in
 * `styles/` so the whole vocabulary ships inside the registry item — a
 * consumer who runs `npx shadcn add @interlace/data-state` gets the hatch,
 * not a reference to a stylesheet they do not have. `image:` is the explicit
 * type hint; without it Tailwind has to guess the property from a `repeating-
 * linear-gradient(...)` value.
 *
 * `--viz-axis` and not `--viz-grid`: the grid token is documented as
 * decorative (1.37:1) and must never be the sole carrier of a value. The hatch
 * IS the value here, so it uses the axis token, measured at 3.49:1 light /
 * 3.83:1 dark — clearing WCAG 2.2 SC 1.4.11 for non-text content.
 */
export const HATCH_CLASS =
  'bg-[image:repeating-linear-gradient(45deg,var(--viz-axis)_0,var(--viz-axis)_1px,transparent_1px,transparent_5px)]';

/** The same hatch, quieter, for states that recede rather than report. */
export const HATCH_CLASS_FAINT =
  'bg-[image:repeating-linear-gradient(45deg,var(--viz-grid)_0,var(--viz-grid)_1px,transparent_1px,transparent_5px)]';

/**
 * Everything a surface needs to paint one state.
 *
 * `glyph` and `short` are BOTH here because the two carriers serve different
 * widths: a meter cell has room for a glyph, a stat strip has room for a word.
 * Neither is ever the only carrier — `announceDataState` is.
 */
export interface DataStatePresentation {
  /** One-character mark. Always `aria-hidden`; the sentence carries meaning. */
  glyph: string;
  /** Terse visible label, lower case, for a chip. */
  short: string;
  /** Diagonal hatch — no run happened. */
  hatch: boolean;
  /** Dashed outline — planned, or not yet approached. Solid means real. */
  dashed: boolean;
  emphasis: DataStateEmphasis;
  /**
   * Tailwind classes for the chip SURFACE. Never the hatch.
   *
   * The first browser pass painted `HATCH_CLASS` on the chip itself and the
   * diagonals ran straight through "not counted", which is a legibility bug
   * axe cannot see and jsdom cannot render — it reports every box as 0×0 and
   * resolves no Tailwind at all. The hatch moved to `swatch`, a leading block
   * that carries the texture beside the words instead of behind them.
   */
  chip: string;
  /**
   * Classes for the leading hatch swatch, or `''` when this state has none.
   * Replaces `glyph` when present — a texture and a character competing for
   * the same 12px is two marks saying one thing badly.
   */
  swatch: string;
}

/**
 * The state → pixels table.
